///////// 1. 변수 및 선언 영역 /////////
scwin.gRsnClssCdList = "";
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.url_form_cd = "";
// 화면 리사이징

scwin.gDepCd;
scwin.gUpDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
