scwin.gKeyword;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
}; // 검색엔진용 채권서식코드는  get방식 사이즈초과로 java소스로 옴김(2011.12.29)

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    scwin.gUpDepCd = js_belngdepcd;
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        panel_mkt.hide();
    }
    panel_mkt.hide(); // 모두 숨김

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34' || js_bond_yn === 'Y') {
        panel_dep_emp.show("");
        scwin.gDepCd = "UPTEAM";
    } else {
        panel_dep_emp.hide();
    }

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    // edt_FromDate.text = cGetMinusDate2(vCurDate, 7);     // 일주일전 날짜
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("gDepCd-->"+gDepCd);
    // setObjectValue(cmb_TeamList, " ");

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 업종 셋팅
    const sbmOptions3 = {
        id : "sbm_dts_IndTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_IndTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
