목록검색;
클릭-- > async function() {
    let vIsurCd = txb_isur_cd.getValue();
    const vFssUnqNm = txb_FssUnqNm.getValue();
    const vFormCd = txb_FormCd.getValue();
    const vFormNm = txb_FormNm.getValue();
    const vRsnclssCnt = txb_rsn_cnt.getValue();
    let vKeyword = txb_keyword.getValue();

    /*
    if (vKeyword == '' ) {
    	if (vIsurCd == '' &&  vFssUnqNm == '' && vFormNm == ''
    		&& (vRsnclssCnt =='' || vRsnclssCnt == '0') ) {
    		alert("법인코드(명), 제출의무자명, 공시제목, 사유분류 중 하나 이상을  입력하셔야 합니다." );
    		txb_isur_cd.focus();
    		return;
    	}
    }
     */

    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }

    // 보고서코그 체크
    if (vFormCd.length > 0 && vFormCd.length !== 5) {
        await $c.win.alert("보고서코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) === 0 && scwin.getChkValue(chb_eng_yn) === 0) {
        await $c.win.alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return;
    }

    // 제출유형 체크
    if (scwin.getChkValue(chb_main_yn) === 0 && scwin.getChkValue(chb_atch_yn) === 0) {
        await $c.win.alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    if (await scwin.chkAttchKeyword() === false) {
        return;
    }
    let sRsnClssCdList = "";
    let sFormUpclssCd;
    let sRsnClssCd;
    for (let i = 1; i <= dts_Dscl_Cond.getRowCount(); i++) {
        sFormUpclssCd = dts_Dscl_Cond.getCellData(i, "FORM_UPCLSS_CD");
        sRsnClssCd = dts_Dscl_Cond.getCellData(i, "RSN_CLSS_CD");
        if (sRsnClssCd !== "000") {
            sRsnClssCdList += (sFormUpclssCd + sRsnClssCd + ",");
        }
    }

    // 맨뒤에 ", " 제거 하기
    scwin.gRsnClssCdList = sRsnClssCdList.substr(0, sRsnClssCdList.length - 1);
    scwin.gDepCd = cmb_TeamList.getValue();
    scwin.gEmpNo = cmb_EmpList.getValue();
    if (scwin.gDepCd === "UPTEAM" && js_dep_cd.substr(2, 4) === '00') {
        scwin.gUpDepCd = js_dep_cd;
    }
    fn_Search();
} < !공시상세--;
클릭-- > async function() {
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();

    // 공시본문검색은 채권해제법인제외 조건을 선택하지 못하게 한다.
    // 검색엔진 테이블에 채권공시법인여부 칼럼이 없어서..
    if (txb_keyword.getValue() !== "") {
        chb_ListStatCd.setValue(0);
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(true);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    let url = "";
    let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_CD=" + txb_FormCd.getValue() + "&FORM_NM=" + txb_FormNm.getValue() + "&KEYWORD=" + $c.ut.replaceAll(txb_keyword.getValue(), "&", "＆") + "&FSS_UNQ_NO=" + txb_FssUnqNo.getValue() + "&FSS_UNQ_NM=" + txb_FssUnqNm.getValue() + "&ACNTCLS_MM=" + cmb_month.getValue() + "&IND_TP=" + cmb_IndTp.getValue() + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=4" + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + cmb_Basis.getValue() + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + 'ULDSTF15000_BOND.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.gKeyword = txb_keyword.getValue();
    if (scwin.gKeyword.length > 0) {
        // 본문검색 키워드가있을때 ...
        let iOpCnt = 0;
        if (scwin.gKeyword.indexOf("&") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("|") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("!") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (iOpCnt > 1) {
            await $c.win.alert("본문검색 키워드는 한 개만 사용할 수 있습니다.");
            txb_keyword.focus();
            return;
        }
        if (scwin.pageSize === 0) {
            await $c.win.alert("공시본문내용으로 검색할 경우에는 한페이지당 보여주는 갯수를 '전체'로 사용할 수 없습니다.");
            cmb_PerPage.setValue("50");
            cmb_PerPage.focus();
            return;
        }
        mgrd_Grid.show("");
        grd_Grid.hide();

        // 1. 검색 건수부터 조회한다.
        url = "/DisclosureSearch.do?method=countDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=SCN_CNTSTAT_OUT";

        // alert("본문검색 카운트: "+url + url_cond);

        dts_scn_list.DataID = encodeURI(url + url_cond + scwin.url_form_cd);
        dts_scn_list.reset();
        const vScnCur = dts_scn_list.getCellData(dts_scn_list.getRowCount(), "SCN_CUR");
        // alert(dts_scn_list.CountRow +", "+vScnCur);

        if (dts_scn_list.getRowCount() > 0) {
            // 2.  Docruzer으로 검색
            url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
            url_cond += "&SCN_NM=" + vScnCur;
            // url_cond += "&SCN_NM=discls_internal";
            // alert("본문검색: "+url + url_cond);

            // alert("url_form_cd-->"+url_form_cd);

            // alert("url-->"+url + url_cond + url_form_cd);

            dts_DsclList.DataID = encodeURI(url + url_cond + scwin.url_form_cd);
            dts_DsclList.reset();
            panel_scn.show("");
            mgrd_Grid.show("");
            grd_Grid.hide();
        } else {
            // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
            btn_Search.setDisabled(false);
            btn_Search.setBackgroundImage("../img/btn_select.gif");
            scwin.vCurrPageNo = 0;
            dts_DsclList_excel.removeAll();
            dts_DsclList.removeAll();
            // showObj(mgrd_Grid, true);
            // showObj(grd_Grid, false);
        }
    } else {
        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Search.setDisabled(true);
        btn_Search.setBackgroundImage("../img/btn_select_d.gif");

        // 본문검색 키워드가 없을때 ... 일반 DB검색
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrchBond" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
        dts_DsclList.DataID = encodeURI(url + url_cond);
        dts_DsclList.reset();
        panel_scn.hide();
        mgrd_Grid.hide();
        grd_Grid.show("");
    }
};

