/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name resetParam
 * @description reset Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34' || js_bond_yn === 'Y') {
        scwin.gDepCd = "UPTEAM";
        cmb_TeamList.setValue(scwin.gDepCd);
    }
    txb_isur_cd.setValue("");
    txb_com_abbrv.setValue("");
    edt_FromDate.setValue(vCurrDate);
    edt_ToDate.setValue(vCurrDate);
    cmb_EmpList.setValue("");
    // setChkValue(chb_ListStatCd, false);
    scwin.setChkValue(chb_ListStatCd, true); // 채권상폐법인제외 체크박스의 디폴트값을 체크하는것으로 변경 by LDJ 20130813 송은진 과장님 요청사항 반영
    scwin.setChkValue(chb_Last, false);
    txb_FormCd.setValue("");
    txb_FormNm.setValue("");
    txb_keyword.setValue("");
    txb_FssUnqNo.setValue("");
    txb_FssUnqNm.setValue("");
    cmb_month.setValue("");
    cmb_IndTp.setValue("");
    scwin.setChkValue(chb_kor_yn, true);
    scwin.setChkValue(chb_eng_yn, true);
    rdo_MKT_ID.setValue(js_market);
    scwin.setChkValue(chb_main_yn, true);
