/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        // 2017-11-24 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF15000_BOND.xml');
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name mgrd_Grid_OnLButtonDblClk
 * @description 클릭된 값 변수에 셋팅
