 */
scwin.txb_keyword_onblur = function() {
    if (txb_keyword.getValue() !== "") {
        chb_ListStatCd.setValue(0);
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    grd_Grid_excel.hide();
    mgrd_Grid_excel.hide();
    panel_scn.hide();
    mgrd_Grid.hide();
    txb_FssUnqNo.hide();
    scwin.setChkValue(chb_ListStatCd, true); // 채권상폐법인제외 체크박스의 디폴트값을 체크하는것으로 변경 by LDJ 20130813 송은진 과장님 요청사항 반영

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    await scwin.setCode();
    $c.stf.comboCbDataSet(cmb_PerPage);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_Dscl_Cond",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Dscl_Cond=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
    showload.style.display = "none";
};
